def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    opp = [h[1] for h in history]
    opp_def = sum(1 for a in opp if a == 'D')

    # Probe at round 21 (n=20) to test if opponent is unconditionally cooperative
    if n == 20:
        return 'D'

    # If opponent never defected after the probe, exploit by defecting
    if n > 20 and opp_def == 0:
        return 'D'

    last_op = history[-1][1]

    # Early game: be very forgiving
    if n < 5:
        return 'C'

    if last_op == 'D':
        # Retaliate if opponent is defecting frequently
        if opp_def / n > 0.5:
            return 'D'
        # Retaliate if opponent defected in at least 3 of the last 5 rounds
        recent = opp[-5:]
        if sum(1 for a in recent if a == 'D') >= 3:
            return 'D'
        # Otherwise forgive a single defection
        return 'C'
    else:
        return 'C'
